"""Query planning, expression evaluation, and CSV access for minisql."""

import csv
import functools
import os
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, List, Optional, Sequence, Tuple

from .errors import QueryError
from .parser import (
    Between,
    Binary,
    Call,
    Column,
    Expr,
    InList,
    IsNull,
    Like,
    Literal,
    OutputRef,
    Paren,
    Query,
    Unary,
    expr_key,
)


# ---------------------------------------------------------------------------
# CSV tables


@dataclass
class Table:
    name: str
    columns: List[str]
    rows: List[Tuple[Any, ...]]


_INTEGER_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


def _convert_field(field: str) -> Any:
    if field == "":
        return None
    if _INTEGER_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def load_table(name: str, directory: str) -> Table:
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table %r is empty" % name)

            rows: List[Tuple[Any, ...]] = []
            for raw in reader:
                if not raw:
                    # A blank line has no fields at all; treat it as no row.
                    continue
                values = [_convert_field(field) for field in raw[: len(header)]]
                if len(values) < len(header):
                    values.extend([None] * (len(header) - len(values)))
                rows.append(tuple(values))
            return Table(name=name, columns=header, rows=rows)
    except QueryError:
        raise
    except FileNotFoundError:
        raise QueryError("no such table: %s" % name)
    except (OSError, UnicodeError, csv.Error) as exc:
        raise QueryError("could not read table %s: %s" % (name, exc))


# ---------------------------------------------------------------------------
# Planning


AGGREGATES = {"count", "sum", "avg", "min", "max"}
SCALARS = {
    "lower": (1, 1),
    "upper": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "round": (1, 2),
    "coalesce": (1, None),
}


@dataclass
class Plan:
    output_exprs: List[Expr]
    output_names: List[str]
    order_exprs: List[Expr]
    order_desc: List[bool]
    grouped: bool
    group_by: List[Expr]
    where: Optional[Expr]
    having: Optional[Expr]


class Binder:
    def __init__(self, query: Query, table: Table):
        self.query = query
        self.table = table
        self.lookup = {}
        for index, name in enumerate(table.columns):
            self.lookup.setdefault(name.casefold(), index)
        self.has_aggregate = False

    def bind(self) -> Plan:
        query = self.query
        table = self.table

        if query.where is not None:
            self.bind_expr(query.where, in_where=True)

        for group_expr in query.group_by:
            self.bind_expr(group_expr, in_group_by=True)

        if query.having is not None:
            self.bind_expr(query.having)

        output_exprs: List[Expr] = []
        output_names: List[str] = []
        for item in query.items:
            if item.star:
                for index, header_name in enumerate(table.columns):
                    output_exprs.append(
                        Column(
                            start=0,
                            end=0,
                            name=header_name,
                            quoted=True,
                            index=index,
                        )
                    )
                    output_names.append(header_name)
                continue

            expr = item.expr
            assert expr is not None
            self.bind_expr(expr)
            if item.alias is not None:
                name = item.alias
            elif isinstance(expr, Column):
                name = table.columns[expr.index]  # type: ignore[index]
            else:
                name = query.sql[expr.start : expr.end]
            output_exprs.append(expr)
            output_names.append(name)

        order_exprs: List[Expr] = []
        order_desc: List[bool] = []
        for order_item in query.order_by:
            expr = order_item.expr
            resolved = self.resolve_order_ref(expr, output_names)
            if resolved is None:
                self.bind_expr(expr)
                resolved = expr
            order_exprs.append(resolved)
            order_desc.append(order_item.descending)

        grouped = bool(query.group_by) or self.has_aggregate

        if grouped:
            group_keys = {expr_key(expr) for expr in query.group_by}
            for expr in output_exprs:
                self.check_grouped(expr, group_keys)
            if query.having is not None:
                self.check_grouped(query.having, group_keys)
            for expr in order_exprs:
                if not isinstance(expr, OutputRef):
                    self.check_grouped(expr, group_keys)

        return Plan(
            output_exprs=output_exprs,
            output_names=output_names,
            order_exprs=order_exprs,
            order_desc=order_desc,
            grouped=grouped,
            group_by=list(query.group_by),
            where=query.where,
            having=query.having,
        )

    def resolve_order_ref(
        self, expr: Expr, output_names: Sequence[str]
    ) -> Optional[OutputRef]:
        if isinstance(expr, Column):
            name = expr.name
            if expr.quoted:
                for index, output_name in enumerate(output_names):
                    if output_name == name:
                        return OutputRef(
                            start=expr.start, end=expr.end, index=index
                        )
            folded = name.casefold()
            for index, output_name in enumerate(output_names):
                if output_name.casefold() == folded:
                    return OutputRef(start=expr.start, end=expr.end, index=index)
            return None

        if isinstance(expr, Literal) and type(expr.value) is int:
            position = expr.value
            if 1 <= position <= len(output_names):
                return OutputRef(
                    start=expr.start, end=expr.end, index=position - 1
                )
            raise QueryError(
                "ORDER BY position %d is not in the select list" % position
            )

        return None

    def bind_expr(
        self,
        expr: Expr,
        in_where: bool = False,
        in_group_by: bool = False,
        in_aggregate: bool = False,
    ) -> None:
        if isinstance(expr, Literal) or isinstance(expr, OutputRef):
            return

        if isinstance(expr, Column):
            if expr.index is not None:
                return
            key = expr.name.casefold()
            if key not in self.lookup:
                raise QueryError("no such column: %s" % expr.name)
            expr.index = self.lookup[key]
            return

        if isinstance(expr, Paren):
            self.bind_expr(expr.operand, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, Unary):
            self.bind_expr(expr.operand, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, Binary):
            self.bind_expr(expr.left, in_where, in_group_by, in_aggregate)
            self.bind_expr(expr.right, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, IsNull):
            self.bind_expr(expr.operand, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, InList):
            self.bind_expr(expr.operand, in_where, in_group_by, in_aggregate)
            for item in expr.items:
                self.bind_expr(item, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, Between):
            self.bind_expr(expr.operand, in_where, in_group_by, in_aggregate)
            self.bind_expr(expr.low, in_where, in_group_by, in_aggregate)
            self.bind_expr(expr.high, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, Like):
            self.bind_expr(expr.operand, in_where, in_group_by, in_aggregate)
            self.bind_expr(expr.pattern, in_where, in_group_by, in_aggregate)
            return

        if isinstance(expr, Call):
            lowered = expr.name.casefold()

            if lowered in AGGREGATES:
                if in_where:
                    raise QueryError(
                        "aggregate functions are not allowed in WHERE"
                    )
                if in_group_by:
                    raise QueryError(
                        "aggregate functions are not allowed in GROUP BY"
                    )
                if in_aggregate:
                    raise QueryError("aggregate functions can't be nested")

                if lowered == "count":
                    if not expr.star and len(expr.args) != 1:
                        raise QueryError("COUNT takes one argument")
                else:
                    if expr.star or len(expr.args) != 1:
                        raise QueryError(
                            "%s takes one argument" % expr.name.upper()
                        )

                expr.is_aggregate = True
                self.has_aggregate = True
                for arg in expr.args:
                    self.bind_expr(
                        arg,
                        in_where=in_where,
                        in_group_by=in_group_by,
                        in_aggregate=True,
                    )
                return

            if lowered in SCALARS:
                if expr.star:
                    raise QueryError(
                        "%s does not take *" % expr.name.upper()
                    )
                minimum, maximum = SCALARS[lowered]
                count = len(expr.args)
                if count < minimum or (
                    maximum is not None and count > maximum
                ):
                    if maximum is None:
                        expected = "at least %d" % minimum
                    elif minimum == maximum:
                        expected = "%d" % minimum
                    else:
                        expected = "%d to %d" % (minimum, maximum)
                    raise QueryError(
                        "%s takes %s argument(s)"
                        % (expr.name.upper(), expected)
                    )
                for arg in expr.args:
                    self.bind_expr(
                        arg,
                        in_where=in_where,
                        in_group_by=in_group_by,
                        in_aggregate=in_aggregate,
                    )
                return

            raise QueryError("unknown function: %s" % expr.name)

        raise QueryError("invalid expression")

    def check_grouped(self, expr: Expr, group_keys) -> None:
        if isinstance(expr, Call) and expr.is_aggregate:
            return
        if expr_key(expr) in group_keys:
            return

        if isinstance(expr, Column):
            raise QueryError(
                "column %r must appear in GROUP BY or be used in an aggregate"
                % expr.name
            )

        if isinstance(expr, Paren):
            self.check_grouped(expr.operand, group_keys)
        elif isinstance(expr, Unary):
            self.check_grouped(expr.operand, group_keys)
        elif isinstance(expr, Binary):
            self.check_grouped(expr.left, group_keys)
            self.check_grouped(expr.right, group_keys)
        elif isinstance(expr, IsNull):
            self.check_grouped(expr.operand, group_keys)
        elif isinstance(expr, InList):
            self.check_grouped(expr.operand, group_keys)
            for item in expr.items:
                self.check_grouped(item, group_keys)
        elif isinstance(expr, Between):
            self.check_grouped(expr.operand, group_keys)
            self.check_grouped(expr.low, group_keys)
            self.check_grouped(expr.high, group_keys)
        elif isinstance(expr, Like):
            self.check_grouped(expr.operand, group_keys)
            self.check_grouped(expr.pattern, group_keys)
        elif isinstance(expr, Call):
            for arg in expr.args:
                self.check_grouped(arg, group_keys)


# ---------------------------------------------------------------------------
# Value helpers


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value: Any) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def compare_values(left: Any, right: Any) -> int:
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if _is_number(left) and _is_number(right):
        return (left > right) - (left < right)
    if isinstance(left, str) and isinstance(right, str):
        return (left > right) - (left < right)
    if isinstance(left, bool) and isinstance(right, bool):
        return (left > right) - (left < right)
    raise QueryError(
        "cannot compare %s with %s"
        % (_type_name(left), _type_name(right))
    )


def _truth(value: Any) -> Optional[bool]:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError("expected a boolean, got %s" % _type_name(value))


def _text(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if _is_number(value):
        return str(value)
    raise QueryError("cannot convert %s to text" % _type_name(value))


def _and3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _value_key(value: Any):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if _is_number(value):
        return ("num", value)
    if isinstance(value, str):
        return ("str", value)
    return ("other", repr(value))


def _round_away(value: Any, digits: Optional[int] = None) -> Any:
    if digits is None and type(value) is int:
        return value

    if type(value) is int:
        decimal_value = Decimal(value)
    else:
        decimal_value = Decimal(repr(float(value)))

    if digits is None:
        try:
            return int(
                decimal_value.quantize(
                    Decimal(1), rounding=ROUND_HALF_UP
                )
            )
        except InvalidOperation:
            return int(decimal_value)

    try:
        quantum = Decimal(1).scaleb(-digits)
        return float(
            decimal_value.quantize(quantum, rounding=ROUND_HALF_UP)
        )
    except InvalidOperation:
        return float(value)


_LIKE_CACHE = {}


def _like_regex(pattern: str):
    regex = _LIKE_CACHE.get(pattern)
    if regex is None:
        pieces = []
        for char in pattern:
            if char == "%":
                pieces.append(".*")
            elif char == "_":
                pieces.append(".")
            else:
                pieces.append(re.escape(char))
        regex = re.compile("".join(pieces), re.DOTALL)
        _LIKE_CACHE[pattern] = regex
    return regex


def _compare_for_sort(left: Any, right: Any, descending: bool) -> int:
    if left is None or right is None:
        if left is None and right is None:
            return 0
        if left is None:
            return 1 if descending else -1
        return -1 if descending else 1

    result = compare_values(left, right)
    return -result if descending else result


# ---------------------------------------------------------------------------
# Evaluation


class Evaluator:
    def __init__(self, table: Table):
        self.table = table

    def eval(
        self,
        expr: Expr,
        row: Optional[Tuple[Any, ...]] = None,
        group: Optional[List[Tuple[Any, ...]]] = None,
    ) -> Any:
        if isinstance(expr, Literal):
            return expr.value

        if isinstance(expr, Column):
            if row is None:
                raise QueryError(
                    "cannot evaluate column %r without a row" % expr.name
                )
            assert expr.index is not None
            return row[expr.index]

        if isinstance(expr, Paren):
            return self.eval(expr.operand, row, group)

        if isinstance(expr, Unary):
            value = self.eval(expr.operand, row, group)
            if value is None:
                return None
            if expr.op == "NOT":
                return not _truth(value)
            if not _is_number(value):
                raise QueryError(
                    "unary - requires a number, got %s" % _type_name(value)
                )
            return -value

        if isinstance(expr, Binary):
            return self.eval_binary(expr, row, group)

        if isinstance(expr, IsNull):
            value = self.eval(expr.operand, row, group)
            result = value is None
            return (not result) if expr.negated else result

        if isinstance(expr, InList):
            return self.eval_in(expr, row, group)

        if isinstance(expr, Between):
            return self.eval_between(expr, row, group)

        if isinstance(expr, Like):
            return self.eval_like(expr, row, group)

        if isinstance(expr, Call):
            if expr.is_aggregate:
                return self.eval_aggregate(expr, group)
            return self.eval_scalar(expr, row, group)

        raise QueryError("invalid expression")

    def eval_binary(
        self,
        expr: Binary,
        row: Optional[Tuple[Any, ...]],
        group: Optional[List[Tuple[Any, ...]]],
    ) -> Any:
        op = expr.op

        if op in ("AND", "OR"):
            left = _truth(self.eval(expr.left, row, group))
            if op == "AND":
                if left is False:
                    return False
                right = _truth(self.eval(expr.right, row, group))
                if left is True:
                    return right
                return False if right is False else None

            if left is True:
                return True
            right = _truth(self.eval(expr.right, row, group))
            if left is False:
                return right
            return True if right is True else None

        left = self.eval(expr.left, row, group)
        right = self.eval(expr.right, row, group)

        if op in ("=", "!=", "<", "<=", ">", ">="):
            if left is None or right is None:
                return None
            comparison = compare_values(left, right)
            if op == "=":
                return comparison == 0
            if op == "!=":
                return comparison != 0
            if op == "<":
                return comparison < 0
            if op == "<=":
                return comparison <= 0
            if op == ">":
                return comparison > 0
            return comparison >= 0

        if op == "||":
            if left is None or right is None:
                return None
            return _text(left) + _text(right)

        if left is None or right is None:
            return None

        if not _is_number(left) or not _is_number(right):
            raise QueryError(
                "arithmetic on %s and %s is not supported"
                % (_type_name(left), _type_name(right))
            )

        if op == "/":
            if right == 0:
                return None
            return left / right

        if type(left) is int and type(right) is int:
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            return left * right

        left_float = float(left)
        right_float = float(right)
        if op == "+":
            return left_float + right_float
        if op == "-":
            return left_float - right_float
        return left_float * right_float

    def eval_in(
        self,
        expr: InList,
        row: Optional[Tuple[Any, ...]],
        group: Optional[List[Tuple[Any, ...]]],
    ) -> Any:
        value = self.eval(expr.operand, row, group)
        if value is None:
            return None

        saw_null = False
        result: Optional[bool] = False
        for item_expr in expr.items:
            item = self.eval(item_expr, row, group)
            if item is None:
                saw_null = True
                continue
            if compare_values(value, item) == 0:
                result = True
                break

        if result is False and saw_null:
            result = None
        if expr.negated and result is not None:
            result = not result
        return result

    def eval_between(
        self,
        expr: Between,
        row: Optional[Tuple[Any, ...]],
        group: Optional[List[Tuple[Any, ...]]],
    ) -> Any:
        value = self.eval(expr.operand, row, group)
        low = self.eval(expr.low, row, group)
        high = self.eval(expr.high, row, group)

        lower: Optional[bool] = None
        if value is not None and low is not None:
            lower = compare_values(low, value) <= 0
        upper: Optional[bool] = None
        if value is not None and high is not None:
            upper = compare_values(value, high) <= 0

        result = _and3(lower, upper)
        if expr.negated and result is not None:
            result = not result
        return result

    def eval_like(
        self,
        expr: Like,
        row: Optional[Tuple[Any, ...]],
        group: Optional[List[Tuple[Any, ...]]],
    ) -> Any:
        value = self.eval(expr.operand, row, group)
        pattern = self.eval(expr.pattern, row, group)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError(
                "LIKE requires strings, got %s and %s"
                % (_type_name(value), _type_name(pattern))
            )
        result = _like_regex(pattern).fullmatch(value) is not None
        if expr.negated:
            result = not result
        return result

    def eval_scalar(
        self,
        expr: Call,
        row: Optional[Tuple[Any, ...]],
        group: Optional[List[Tuple[Any, ...]]],
    ) -> Any:
        lowered = expr.name.casefold()

        if lowered == "coalesce":
            for arg in expr.args:
                value = self.eval(arg, row, group)
                if value is not None:
                    return value
            return None

        values = [self.eval(arg, row, group) for arg in expr.args]
        if any(value is None for value in values):
            return None

        if lowered in ("lower", "upper", "length"):
            text = values[0]
            if not isinstance(text, str):
                raise QueryError(
                    "%s requires a string, got %s"
                    % (expr.name.upper(), _type_name(text))
                )
            if lowered == "lower":
                return text.lower()
            if lowered == "upper":
                return text.upper()
            return len(text)

        if lowered == "abs":
            number = values[0]
            if not _is_number(number):
                raise QueryError(
                    "ABS requires a number, got %s" % _type_name(number)
                )
            return abs(number)

        if lowered == "round":
            number = values[0]
            if not _is_number(number):
                raise QueryError(
                    "ROUND requires a number, got %s" % _type_name(number)
                )
            if len(values) == 1:
                return _round_away(number)
            digits = values[1]
            if not isinstance(digits, int) or isinstance(digits, bool):
                raise QueryError(
                    "ROUND's second argument must be an integer"
                )
            return _round_away(number, digits)

        raise QueryError("unknown function: %s" % expr.name)

    def eval_aggregate(
        self,
        expr: Call,
        group: Optional[List[Tuple[Any, ...]]],
    ) -> Any:
        if group is None:
            raise QueryError("aggregate used outside a grouped query")

        lowered = expr.name.casefold()

        if lowered == "count":
            if expr.star:
                return len(group)
            argument = expr.args[0]
            count = 0
            for row in group:
                if self.eval(argument, row, group) is not None:
                    count += 1
            return count

        argument = expr.args[0]

        if lowered == "sum":
            total: Any = None
            for row in group:
                value = self.eval(argument, row, group)
                if value is None:
                    continue
                if not _is_number(value):
                    raise QueryError(
                        "SUM requires numeric values, got %s"
                        % _type_name(value)
                    )
                total = value if total is None else total + value
            return total

        if lowered == "avg":
            total = 0.0
            count = 0
            for row in group:
                value = self.eval(argument, row, group)
                if value is None:
                    continue
                if not _is_number(value):
                    raise QueryError(
                        "AVG requires numeric values, got %s"
                        % _type_name(value)
                    )
                total += value
                count += 1
            if count == 0:
                return None
            return total / count

        best: Any = None
        found = False
        for row in group:
            value = self.eval(argument, row, group)
            if value is None:
                continue
            if not found:
                best = value
                found = True
                continue
            comparison = compare_values(value, best)
            if (lowered == "min" and comparison < 0) or (
                lowered == "max" and comparison > 0
            ):
                best = value
        return best if found else None


# ---------------------------------------------------------------------------
# Execution


class Result:
    """The result of a query: ``columns`` and ``rows``."""

    def __init__(self, columns: Sequence[str], rows: Sequence[Tuple[Any, ...]]):
        self.columns = list(columns)
        self.rows = list(rows)

    def __iter__(self):
        return iter(self.rows)

    def __len__(self) -> int:
        return len(self.rows)

    def __bool__(self) -> bool:
        return bool(self.rows)

    def __repr__(self) -> str:
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


def execute(query: Query, directory: str) -> Result:
    table = load_table(query.table, directory)
    plan = Binder(query, table).bind()
    evaluator = Evaluator(table)

    def passes(
        expr: Expr,
        row: Optional[Tuple[Any, ...]],
        group: Optional[List[Tuple[Any, ...]]],
    ) -> bool:
        return _truth(evaluator.eval(expr, row, group)) is True

    filtered: List[Tuple[Any, ...]] = []
    if plan.where is None:
        filtered = list(table.rows)
    else:
        for row in table.rows:
            if passes(plan.where, row, None):
                filtered.append(row)

    records: List[Tuple[Tuple[Any, ...], List[Any]]] = []

    if plan.grouped:
        if plan.group_by:
            groups = {}
            for row in filtered:
                key = tuple(
                    _value_key(evaluator.eval(group_expr, row, None))
                    for group_expr in plan.group_by
                )
                groups.setdefault(key, []).append(row)
            group_rows_list = list(groups.values())
        else:
            group_rows_list = [filtered]

        for group_rows in group_rows_list:
            representative = group_rows[0] if group_rows else None
            if plan.having is not None and not passes(
                plan.having, representative, group_rows
            ):
                continue
            values = tuple(
                evaluator.eval(expr, representative, group_rows)
                for expr in plan.output_exprs
            )
            keys = [
                values[expr.index]
                if isinstance(expr, OutputRef)
                else evaluator.eval(expr, representative, group_rows)
                for expr in plan.order_exprs
            ]
            records.append((values, keys))
    else:
        for row in filtered:
            if plan.having is not None and not passes(
                plan.having, row, None
            ):
                continue
            values = tuple(
                evaluator.eval(expr, row, None)
                for expr in plan.output_exprs
            )
            keys = [
                values[expr.index]
                if isinstance(expr, OutputRef)
                else evaluator.eval(expr, row, None)
                for expr in plan.order_exprs
            ]
            records.append((values, keys))

    if query.distinct:
        seen = set()
        distinct_records = []
        for values, keys in records:
            key = tuple(_value_key(value) for value in values)
            if key in seen:
                continue
            seen.add(key)
            distinct_records.append((values, keys))
        records = distinct_records

    if plan.order_exprs:
        descents = plan.order_desc

        def compare_records(left, right) -> int:
            for left_value, right_value, descending in zip(
                left[1], right[1], descents
            ):
                comparison = _compare_for_sort(
                    left_value, right_value, descending
                )
                if comparison:
                    return comparison
            return 0

        records.sort(key=functools.cmp_to_key(compare_records))

    rows = [values for values, _keys in records]

    offset = query.offset or 0
    if offset:
        rows = rows[offset:]
    if query.limit is not None:
        rows = rows[: query.limit]

    return Result(plan.output_names, rows)

