"""Command line entry point for minisql."""

import argparse
import csv
import sys

from . import QueryError, run


def _format_value(value):
    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    return str(value)


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="python -m minisql",
        description="Run a SELECT query against CSV files.",
    )
    parser.add_argument("query", help="the SELECT query to run")
    parser.add_argument(
        "--dir",
        default=".",
        help="directory containing the CSV files (default: .)",
    )
    args = parser.parse_args(argv)

    try:
        result = run(args.query, args.dir)
    except QueryError as exc:
        print(exc, file=sys.stderr)
        return 1

    writer = csv.writer(sys.stdout)
    writer.writerow(result.columns)
    for row in result.rows:
        writer.writerow([_format_value(value) for value in row])
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Tests for minisql. Run with ``python -m unittest discover``."""

import contextlib
import io
import os
import tempfile
import unittest

import minisql
from minisql.__main__ import main as cli_main


PRODUCTS = """id,name,category,price
1,widget,tools,25
2,gadget,toys,12.5
3,doohickey,tools,7
"""

EXTRA = """a,b,c
1,2.5,hello
,3.,it's
-4,.5,
"""

PRICES = """id,"unit price"
1,10
2,
"""


class MiniSqlTest(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.dir = self._tmp.name
        self.write("products.csv", PRODUCTS)
        self.write("extra.csv", EXTRA)
        self.write("prices.csv", PRICES)

    def tearDown(self):
        self._tmp.cleanup()

    def write(self, name, text):
        with open(os.path.join(self.dir, name), "w", encoding="utf-8") as fh:
            fh.write(text)

    def q(self, sql):
        return minisql.run(sql, self.dir)

    def rows(self, sql):
        return self.q(sql).rows

    def assertQueryError(self, sql):
        with self.assertRaises(minisql.QueryError):
            self.q(sql)

    # -- basics ---------------------------------------------------------

    def test_spec_example(self):
        result = self.q(
            "SELECT name, price FROM products WHERE price > 10 "
            "ORDER BY price DESC"
        )
        self.assertEqual(result.columns, ["name", "price"])
        self.assertEqual(result.rows, [("widget", 25), ("gadget", 12.5)])

    def test_csv_conversion(self):
        result = self.q("SELECT a, b, c FROM extra")
        self.assertEqual(result.columns, ["a", "b", "c"])
        self.assertEqual(
            result.rows,
            [
                (1, 2.5, "hello"),
                (None, 3.0, "it's"),
                (-4, 0.5, None),
            ],
        )

    def test_select_star(self):
        result = self.q("SELECT * FROM products")
        self.assertEqual(
            result.columns, ["id", "name", "category", "price"]
        )
        self.assertEqual(len(result.rows), 3)

    def test_case_insensitive_columns_and_keywords(self):
        self.assertEqual(
            self.rows("select NAME from products where PRICE > 20"),
            [("widget",)],
        )

    def test_missing_table_and_column(self):
        self.assertQueryError("SELECT * FROM nope")
        self.assertQueryError("SELECT nope FROM products")

    def test_quoted_names(self):
        result = self.q('SELECT "unit price" FROM prices')
        self.assertEqual(result.columns, ["unit price"])
        self.assertEqual(result.rows, [(10,), (None,)])

    def test_string_escapes(self):
        self.assertEqual(self.rows("SELECT 'it''s' FROM products LIMIT 1"),
                         [("it's",)])

    def test_aliases(self):
        result = self.q("SELECT name, price AS cost FROM products LIMIT 1")
        self.assertEqual(result.columns, ["name", "cost"])
        result = self.q("SELECT name n FROM products LIMIT 1")
        self.assertEqual(result.columns, ["name", "n"])

    def test_default_output_names(self):
        result = self.q("SELECT price * 2 FROM products LIMIT 1")
        self.assertEqual(result.columns, ["price * 2"])
        result = self.q("SELECT COUNT(*) FROM products")
        self.assertEqual(result.columns, ["COUNT(*)"])
        result = self.q("SELECT (price) FROM products LIMIT 1")
        self.assertEqual(result.columns, ["(price)"])

    # -- expressions ----------------------------------------------------

    def test_precedence_and_arithmetic(self):
        self.assertEqual(
            self.rows(
                "SELECT 1 + 2 * 3, (1 + 2) * 3, 10 - 2 - 3, "
                "2 * 3 + 4, -2 * 3 FROM products LIMIT 1"
            ),
            [(7, 9, 5, 10, -6)],
        )

    def test_division(self):
        self.assertEqual(
            self.rows(
                "SELECT 4 / 2, 1 / 2, 1 / 0, 1.0 / 0 "
                "FROM products LIMIT 1"
            ),
            [(2.0, 0.5, None, None)],
        )

    def test_int_and_float_arithmetic(self):
        self.assertEqual(
            self.rows(
                "SELECT 1 + 2, 1 + 2.0, 2 * 3, 2 * 3.0 "
                "FROM products LIMIT 1"
            ),
            [(3, 3.0, 6, 6.0)],
        )

    def test_arithmetic_type_errors(self):
        self.assertQueryError("SELECT 'a' + 1 FROM products")
        self.assertQueryError("SELECT TRUE + 1 FROM products")
        self.assertQueryError("SELECT -'a' FROM products")

    def test_concat(self):
        self.assertEqual(
            self.rows(
                "SELECT 'a' || 1, 1 || 2.5, 'x' || NULL "
                "FROM products LIMIT 1"
            ),
            [("a1", "12.5", None)],
        )

    def test_nulls(self):
        self.assertEqual(
            self.rows(
                "SELECT NULL + 1, NULL = NULL, NULL IS NULL, "
                "NULL IS NOT NULL FROM products LIMIT 1"
            ),
            [(None, None, True, False)],
        )

    def test_three_valued_logic(self):
        self.assertEqual(
            self.rows(
                "SELECT FALSE AND NULL, TRUE AND NULL, TRUE OR NULL, "
                "FALSE OR NULL, NOT NULL FROM products LIMIT 1"
            ),
            [(False, None, True, None, None)],
        )

    def test_where_keeps_true_only(self):
        self.assertEqual(self.rows("SELECT id FROM products WHERE NULL"), [])
        self.assertEqual(
            self.rows("SELECT id FROM products WHERE price > 10"),
            [(1,), (2,)],
        )

    def test_comparisons(self):
        self.assertEqual(
            self.rows(
                "SELECT 1 = 1.0, 1 != 2, 1 <> 1, 'a' < 'b', "
                "TRUE > FALSE FROM products LIMIT 1"
            ),
            [(True, True, False, True, True)],
        )
        self.assertQueryError("SELECT 1 = '1' FROM products")
        self.assertQueryError("SELECT TRUE = 1 FROM products")

    def test_in_and_between(self):
        self.assertEqual(
            self.rows(
                "SELECT 1 IN (2, NULL), 1 IN (1, NULL), "
                "2 NOT IN (1, NULL), 3 BETWEEN NULL AND 2, "
                "NULL BETWEEN 1 AND 2, 5 BETWEEN 4 AND 6 "
                "FROM products LIMIT 1"
            ),
            [(None, True, None, False, None, True)],
        )

    def test_like(self):
        self.assertEqual(
            self.rows(
                "SELECT 'abc' LIKE 'a%', 'abc' LIKE '_b_', "
                "'abc' LIKE 'ab', 'abc' NOT LIKE 'a%', "
                "'a.c' LIKE 'a.c', 'a%c' LIKE 'a.c', "
                "NULL LIKE 'a%' FROM products LIMIT 1"
            ),
            [(True, True, False, False, True, False, None)],
        )

    # -- scalar functions ----------------------------------------------

    def test_scalar_functions(self):
        self.assertEqual(
            self.rows(
                "SELECT LOWER('AbC'), UPPER('AbC'), LENGTH('ab'), "
                "ABS(-3), ABS(-2.5) FROM products LIMIT 1"
            ),
            [("abc", "ABC", 2, 3, 2.5)],
        )

    def test_round(self):
        self.assertEqual(
            self.rows(
                "SELECT ROUND(2.5), ROUND(-2.5), ROUND(2.4), "
                "ROUND(2.345, 2), ROUND(-2.345, 2), ROUND(2, 2) "
                "FROM products LIMIT 1"
            ),
            [(3, -3, 2, 2.35, -2.35, 2.0)],
        )

    def test_coalesce(self):
        self.assertEqual(
            self.rows(
                "SELECT COALESCE(NULL, 1, 2), COALESCE(NULL, NULL), "
                "COALESCE(1, LOWER(2)) FROM products LIMIT 1"
            ),
            [(1, None, 1)],
        )

    def test_scalar_null_propagation(self):
        self.assertEqual(
            self.rows(
                "SELECT LOWER(NULL), ROUND(NULL), ROUND(1, NULL) "
                "FROM products LIMIT 1"
            ),
            [(None, None, None)],
        )

    def test_function_errors(self):
        self.assertQueryError("SELECT NOPE(1) FROM products")
        self.assertQueryError("SELECT LOWER() FROM products")
        self.assertQueryError("SELECT LOWER('a', 'b') FROM products")
        self.assertQueryError("SELECT ROUND(1, 2, 3) FROM products")
        self.assertQueryError("SELECT LOWER(1) FROM products")
        self.assertQueryError("SELECT COUNT(*) FROM products WHERE SUM(price) > 1")

    # -- aggregates and grouping ----------------------------------------

    def test_aggregates(self):
        self.assertEqual(
            self.rows(
                "SELECT COUNT(*), COUNT(price), SUM(price), AVG(price), "
                "MIN(price), MAX(price) FROM products"
            ),
            [(3, 3, 44.5, 44.5 / 3, 7, 25)],
        )

    def test_aggregates_of_integers(self):
        self.assertEqual(
            self.rows("SELECT SUM(id), AVG(id) FROM products"),
            [(6, 2.0)],
        )

    def test_aggregates_on_empty_set(self):
        self.assertEqual(
            self.rows(
                "SELECT COUNT(*), SUM(price), AVG(price), "
                "MIN(price), MAX(price) FROM products WHERE FALSE"
            ),
            [(0, None, None, None, None)],
        )
        self.assertEqual(
            self.rows("SELECT COUNT(*) FROM products WHERE FALSE"),
            [(0,)],
        )

    def test_aggregates_ignore_null(self):
        self.assertEqual(
            self.rows(
                "SELECT COUNT(b), SUM(b), AVG(b), MIN(b), MAX(b) FROM extra"
            ),
            [(2, 3.5, 1.75, 0.5, 3.0)],
        )

    def test_grouping(self):
        self.assertEqual(
            self.rows(
                "SELECT category, COUNT(*), SUM(price) "
                "FROM products GROUP BY category"
            ),
            [("tools", 2, 32), ("toys", 1, 12.5)],
        )

    def test_grouping_expression(self):
        self.assertEqual(
            self.rows(
                "SELECT UPPER(category), COUNT(*) FROM products "
                "GROUP BY category ORDER BY category"
            ),
            [("TOOLS", 2), ("TOYS", 1)],
        )

    def test_having(self):
        self.assertEqual(
            self.rows(
                "SELECT category, COUNT(*) FROM products GROUP BY category "
                "HAVING COUNT(*) > 1"
            ),
            [("tools", 2)],
        )

    def test_having_without_grouping_filters_rows(self):
        self.assertEqual(
            self.rows(
                "SELECT name FROM products HAVING price > 10 ORDER BY name"
            ),
            [("gadget",), ("widget",)],
        )

    def test_aggregate_in_order_by_groups(self):
        self.assertEqual(
            self.rows(
                "SELECT category FROM products GROUP BY category "
                "ORDER BY COUNT(*) DESC"
            ),
            [("tools",), ("toys",)],
        )
        self.assertQueryError(
            "SELECT category FROM products ORDER BY COUNT(*)"
        )

    def test_grouping_nested_aggregate_function(self):
        self.assertEqual(
            self.rows("SELECT ROUND(AVG(price), 2) FROM products"),
            [(14.83,)],
        )

    def test_grouping_errors(self):
        self.assertQueryError("SELECT category, COUNT(*) FROM products")
        self.assertQueryError(
            "SELECT price FROM products GROUP BY category"
        )
        self.assertQueryError("SELECT SUM(COUNT(*)) FROM products")
        self.assertQueryError(
            "SELECT category FROM products GROUP BY category "
            "ORDER BY price"
        )

    # -- distinct, ordering, limits -------------------------------------

    def test_distinct(self):
        self.assertEqual(
            self.rows("SELECT DISTINCT category FROM products"),
            [("tools",), ("toys",)],
        )
        self.assertEqual(
            self.rows(
                "SELECT DISTINCT category FROM products ORDER BY category DESC"
            ),
            [("toys",), ("tools",)],
        )

    def test_null_ordering(self):
        self.assertEqual(
            self.rows("SELECT a FROM extra ORDER BY a"),
            [(-4,), (1,), (None,)],
        )
        self.assertEqual(
            self.rows("SELECT a FROM extra ORDER BY a DESC"),
            [(None,), (1,), (-4,)],
        )

    def test_multi_key_ordering(self):
        self.assertEqual(
            self.rows(
                "SELECT name, category FROM products "
                "ORDER BY category, name DESC"
            ),
            [("widget", "tools"), ("doohickey", "tools"), ("gadget", "toys")],
        )

    def test_order_by_ordinal(self):
        self.assertEqual(
            self.rows("SELECT name, price FROM products ORDER BY 2 DESC"),
            [("widget", 25), ("gadget", 12.5), ("doohickey", 7)],
        )
        self.assertQueryError(
            "SELECT name FROM products ORDER BY 2"
        )

    def test_order_by_output_alias(self):
        self.assertEqual(
            self.rows(
                'SELECT "unit price" AS up FROM prices ORDER BY up DESC'
            ),
            [(10,), (None,)],
        )

    def test_order_by_input_expression(self):
        self.assertEqual(
            self.rows("SELECT name FROM products ORDER BY price DESC"),
            [("widget",), ("gadget",), ("doohickey",)],
        )

    def test_limit_offset(self):
        self.assertEqual(
            self.rows(
                "SELECT name FROM products ORDER BY price DESC "
                "LIMIT 2 OFFSET 1"
            ),
            [("gadget",), ("doohickey",)],
        )
        self.assertEqual(
            self.rows("SELECT name FROM products LIMIT 0"), []
        )

    def test_stable_order(self):
        self.assertEqual(
            self.rows("SELECT name FROM products ORDER BY category"),
            [("widget",), ("doohickey",), ("gadget",)],
        )

    # -- errors ---------------------------------------------------------

    def test_syntax_errors(self):
        for sql in [
            "",
            "SELECT",
            "SELECT * FROM",
            "SELECT * products",
            "SELECT * FROM products WHERE",
            "SELECT * FROM products; SELECT 1 FROM products",
            "SELECT * FROM products LIMIT 1.5",
            "SELECT * FROM products LIMIT -1",
            "SELECT *, id FROM products",
        ]:
            self.assertQueryError(sql)

    # -- command line ---------------------------------------------------

    def test_cli(self):
        out = io.StringIO()
        err = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            status = cli_main(
                [
                    "SELECT name, price FROM products ORDER BY price DESC "
                    "LIMIT 1",
                    "--dir",
                    self.dir,
                ]
            )
        self.assertEqual(status, 0)
        self.assertEqual(out.getvalue(), "name,price\r\nwidget,25\r\n")
        self.assertEqual(err.getvalue(), "")

    def test_cli_null_and_boolean(self):
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(
            io.StringIO()
        ):
            status = cli_main(
                [
                    "SELECT NULL, TRUE, FALSE FROM products LIMIT 1",
                    "--dir",
                    self.dir,
                ]
            )
        self.assertEqual(status, 0)
        self.assertEqual(out.getvalue(), "\r\n,,true,false\r\n")

    def test_cli_error(self):
        out = io.StringIO()
        err = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            status = cli_main(
                ["SELECT * FROM missing", "--dir", self.dir]
            )
        self.assertEqual(status, 1)
        self.assertEqual(out.getvalue(), "")
        self.assertTrue(err.getvalue().strip())


